"""Company sales offer screen; all calculations and persistence use the server."""
HTML = '''<div data-view="propuestas-ventas" hidden>
<div class="so-workspace"><section class="card so-editor"><h2>PROPUESTAS DE VENTA</h2><p>Prepara una oferta para un cliente con varias líneas. Los precios y las existencias son referencias de la versión documental activa.</p>
<form id="sales-offer-form"><div class="fields"><label>Cliente<select id="so-customer" required></select></label><label>Referencia de la oferta<input id="so-reference" maxlength="100" required></label><label>Fecha de la oferta<input id="so-date" placeholder="DD/MM/AAAA" required></label><label>Válida hasta<input id="so-valid" placeholder="DD/MM/AAAA" required></label></div>
<div id="so-lines"></div><button id="so-add" type="button">+ Añadir artículo</button>
<div class="fields"><label>Entrega prevista<input id="so-delivery-date" placeholder="DD/MM/AAAA" required></label><label>Lugar de entrega<input id="so-delivery" maxlength="500" required></label><label>Cobro previsto<input id="so-due" placeholder="DD/MM/AAAA" required></label><label>Condiciones de cobro<input id="so-payment" maxlength="500" required></label><label>Portes facturados al cliente, sin IVA (€)<input id="so-freight" inputmode="decimal" value="0" required></label><label>IVA de los portes (%)<input id="so-freight-vat" inputmode="decimal" required></label></div>
<div class="fields"><label>Coste logístico previsto para la empresa, sin IVA (€)<input id="so-seller-freight" inputmode="decimal" placeholder="Declara 0 si no existe coste"></label><label>Posible regalo de merchandising (opción interna)<input id="so-gift-description" maxlength="300" placeholder="Ej.: gorra promocional"></label><label>Coste total previsto del regalo (€)<input id="so-gift-cost" inputmode="decimal" value="0"></label></div><p>El merchandising se estudia como opción interna: no queda comprometido ni incluido fiscalmente en el documento del cliente.</p><p>Importes en EUR. Introduce expresamente el IVA aplicable; EIOS no lo deduce del cliente o del artículo. Usa números como 1.234,50.</p>
<div class="files-actions"><button id="so-preview" type="button">Calcular oferta</button><button class="primary" id="so-save" type="submit">Guardar propuesta de venta</button></div><p id="so-notice" role="status"></p><div id="so-summary"></div></form></section><aside class="so-assistant"><section class="card"><h2>APOYO AL COMERCIAL</h2><p>Precio de origen y referencias del artículo antes de negociar.</p><button id="so-policy" type="button">Configurar margen mínimo y objetivo</button><div id="so-article-advice"></div></section><section class="card"><h2>NEGOCIACIÓN Y PROTECCIÓN ECONÓMICA</h2><p>Calcula la oferta para contrastar precio, descuentos, portes y merchandising con los márgenes configurados y el contexto financiero.</p><div id="so-negotiation"></div></section></aside></div>
<section class="card"><h2>OFERTAS GUARDADAS</h2><p>Consulta e imprime la versión guardada para el cliente. El documento excluye costes y márgenes internos.</p><div class="scroll"><table><thead><tr><th>Referencia / fecha</th><th>Cliente</th><th>Total</th><th>Vigencia</th><th>Documento</th></tr></thead><tbody id="so-saved"></tbody></table></div></section></div>'''
CSS = '''.so-workspace{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(350px,.8fr);gap:24px;align-items:start}.so-workspace>*{min-width:0}.so-assistant{position:sticky;top:16px;max-height:calc(100vh - 32px);overflow:auto}.so-assistant h2{font-size:18px}.so-assistance{border-top:1px solid #cad9e9;padding-top:15px;margin-top:15px}.so-advice-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.so-advice-grid div{background:#eaf2fd;padding:12px;border-radius:6px}.so-advice-grid small,.so-advice-grid strong{display:block}.so-advice-grid strong{font-size:19px;margin-top:8px}.so-scenario{border:1px solid #c9d9e9;border-radius:8px;padding:15px;margin-top:15px;background:#f7faff}.so-alert{background:#fff2db;border-left:4px solid #c38213;padding:12px;line-height:1.5}@media(max-width:1100px){.so-workspace{grid-template-columns:1fr}.so-assistant{position:static;max-height:none;overflow:visible}}.so-line{border:1px solid #c9d9e9;border-radius:8px;padding:18px;margin:18px 0;background:#f7faff}.so-line h3{margin-top:0}.so-hint{font-size:13px;line-height:1.6;background:#eaf2fd;padding:12px;border-radius:6px}.so-totals{display:flex;flex-wrap:wrap;gap:20px;padding:18px;background:#eaf2fd;border-left:4px solid #0a369d}.so-totals strong{font-size:20px}'''
JS = r'''
let salesOfferVersion=0,salesOfferCalculation=0;
function resetSalesOffers(){resetSalesCash();salesOfferVersion++;salesOfferCalculation++;$('sales-offer-form').reset();$('so-summary').replaceChildren();$('so-notice').textContent='';$('so-lines').replaceChildren();$('so-article-advice').replaceChildren();$('so-negotiation').replaceChildren();$('so-customer').replaceChildren();option($('so-customer'),'','Selecciona un cliente');(state.customers||[]).forEach(c=>option($('so-customer'),c.customer_id,c.legal_name||c.customer_id));addSalesOfferLine();renderSavedSalesOffers()}
function salesOfferField(parent,labelText,key,type='text'){const label=document.createElement('label');label.textContent=labelText;const input=document.createElement(type==='select'?'select':'input');if(type!=='select'){input.type='text';input.inputMode='decimal'}input.dataset.so=key;input.required=true;label.append(input);parent.append(label);return input}
function addSalesOfferLine(){if($('so-lines').children.length>=30)return;const row=document.createElement('section');row.className='so-line';const title=document.createElement('h3');title.textContent='ARTÍCULO';row.append(title);const fields=document.createElement('div');fields.className='fields';const article=salesOfferField(fields,'Artículo / SKU','article_id','select');option(article,'','Selecciona un artículo');state.articles.forEach(a=>option(article,a.article_id,a.article_id+' · '+(a.description||'')+' / '+a.unit_as_documented));salesOfferField(fields,'Cantidad','quantity');salesOfferField(fields,'Precio unitario antes de descuento (€)','unit_price');const discount=salesOfferField(fields,'Descuento de línea (%)','discount_value');discount.value='0';salesOfferField(fields,'IVA de línea (%)','vat_percent');row.append(fields);const hint=document.createElement('p');hint.className='so-hint';row.soHint=hint;hint.className='so-assistance';$('so-article-advice').append(hint);const remove=document.createElement('button');remove.type='button';remove.textContent='Quitar artículo';remove.onclick=()=>{hint.remove();row.remove();$('so-negotiation').replaceChildren();salesOfferCalculation++;$('so-summary').replaceChildren()};row.append(remove);row.soRequest=0;row.querySelector('[data-so=article_id]').onchange=()=>loadSalesOrientation(row);$('so-lines').append(row);loadSalesOrientation(row)}
async function loadSalesOrientation(row){const seq=++row.soRequest,version=salesOfferVersion,dataset=$('dataset').value,article=row.querySelector('[data-so=article_id]').value,customer=$('so-customer').value,hint=row.soHint;hint.textContent='Selecciona cliente y artículo para consultar referencias.';if(!article||!customer)return;try{const r=await api('/api/sales-proposals/context',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,customer_id:customer,article_id:article})});if(!row.isConnected||seq!==row.soRequest||version!==salesOfferVersion||dataset!==$('dataset').value)return;const i=r.inventory;let text=i?'Stock de referencia: '+stockNumber(i.physical)+' físico · '+stockNumber(i.reserved)+' reservado · '+stockNumber(i.available)+' disponible / '+i.unit+' · '+stockDate(i.as_of_date)+' · '+i.material_nature:'Stock: sin datos comparables.';text+=' Últimas ventas comparables al cliente: '+(r.latest_sales.length?r.latest_sales.map(s=>stockDate(s.date)+' · '+stockNumber(s.quantity)+' '+s.unit+' · neto por unidad '+money(s.net_unit_price)+' EUR · '+s.invoice).join(' / '):'sin referencias.');text+=' Compra histórica de referencia: '+(r.reference_unit_cost===null?'sin referencia única comparable.':money(r.reference_unit_cost)+' EUR/unidad; excluye otros costes.');renderSalesArticleAdvice(row,hint,r,article)}catch(e){if(seq===row.soRequest&&version===salesOfferVersion)hint.textContent=e.message}}
function salesOfferData(){return {commercial_parameter_revision:parametersState?.current?.revision||0,seller_freight_cost:parameterNumber($('so-seller-freight').value),gift_description:$('so-gift-description').value.trim(),gift_cost:parameterNumber($('so-gift-cost').value),dataset_id:$('dataset').value,context_fingerprint:state.documentary_context.fingerprint,customer_id:$('so-customer').value,reference:$('so-reference').value.trim(),offer_date:inputDateISO($('so-date').value),valid_until:inputDateISO($('so-valid').value),delivery_date:inputDateISO($('so-delivery-date').value),due_date:inputDateISO($('so-due').value),delivery_location:$('so-delivery').value.trim(),payment_terms:$('so-payment').value.trim(),freight_net:parameterNumber($('so-freight').value),freight_vat_percent:parameterNumber($('so-freight-vat').value),lines:Array.from($('so-lines').children).map(row=>Object.fromEntries(Array.from(row.querySelectorAll('[data-so]')).map(input=>[input.dataset.so,input.dataset.so==='article_id'?input.value:parameterNumber(input.value)])))}}
async function submitSalesOffer(save){if(!$('sales-offer-form').reportValidity())return;const seq=++salesOfferCalculation,version=salesOfferVersion,dataset=$('dataset').value;const button=save?$('so-save'):$('so-preview');button.disabled=true;$('so-notice').textContent='';try{const payload=salesOfferData();const result=await api(save?'/api/sales-proposals':'/api/sales-proposals/preview',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify(payload)});if(version!==salesOfferVersion||dataset!==$('dataset').value)return;if(save){state.sales_proposals.unshift(result);renderSavedSalesOffers();$('so-notice').textContent='Oferta guardada con sus datos de referencia. No reserva stock ni registra una venta.'}if(seq!==salesOfferCalculation)return;result.lines.forEach((line,index)=>{const row=$('so-lines').children[index];if(row&&row.soHint)renderSalesArticleAdvice(row,row.soHint,{...line.orientation,article:state.articles.find(a=>a.article_id===line.article_id),price_reference:result.negotiation.origin_prices[index]},line.article_id)});renderSalesLineNegotiation(result.lines);renderSalesNegotiation(result.negotiation);const box=$('so-summary');box.replaceChildren();const totals=document.createElement('div');totals.className='so-totals';totals.textContent='Base '+money(result.net_amount)+' EUR · IVA '+money(result.vat_amount)+' EUR · TOTAL '+money(result.total)+' EUR';box.append(totals);(result.warnings||[]).forEach(w=>{const p=document.createElement('p');p.textContent=w;box.append(p)});result.lines.forEach(l=>{const p=document.createElement('p');p.textContent=l.article_id+' · Neto '+money(l.net_amount)+' EUR · Margen sobre compra histórica: '+(l.reference_margin_percent===null?'no calculable':money(l.reference_margin_percent)+' %')+'. Excluye portes y otros costes.';box.append(p)});}catch(e){if(version===salesOfferVersion)$('so-notice').textContent=e.message}finally{button.disabled=false}}
function renderSavedSalesOffers(){const box=$('so-saved');box.replaceChildren();(state.sales_proposals||[]).forEach(p=>{const row=document.createElement('tr');salesCells(row,[p.reference+' · '+stockDate(p.offer_date),p.customer.legal_name||p.customer.customer_id,money(p.total)+' EUR',stockDate(p.valid_until)]);const cell=document.createElement('td'),button=document.createElement('button');button.type='button';button.textContent='Documento para el cliente';button.onclick=async()=>{const dataset=$('dataset').value;button.disabled=true;try{const {html}=await api('/api/sales-proposals/report',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:p.proposal_id})});if(dataset!==$('dataset').value)return;const blob=new Blob([html],{type:'text/html'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Propuesta_venta_'+p.proposal_id+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){$('so-notice').textContent=e.message}finally{button.disabled=false}};const planButton=document.createElement('button');planButton.type='button';planButton.textContent='Plan de cobros y pagos';planButton.onclick=()=>openSalesCash(p.proposal_id);cell.append(button,planButton);row.append(cell);box.append(row)});if(!box.children.length){const row=document.createElement('tr');salesCells(row,['Sin ofertas guardadas en esta versión.']);box.append(row)}}
$('so-policy').onclick=()=>view('parametros');$('so-add').onclick=addSalesOfferLine;$('so-customer').onchange=()=>{salesOfferCalculation++;$('so-summary').replaceChildren();$('so-negotiation').replaceChildren();Array.from($('so-lines').children).forEach(loadSalesOrientation)};$('so-preview').onclick=()=>submitSalesOffer(false);$('sales-offer-form').onsubmit=event=>{event.preventDefault();submitSalesOffer(true)};$('sales-offer-form').addEventListener('input',()=>{salesOfferCalculation++;$('so-summary').replaceChildren();$('so-negotiation').replaceChildren();document.querySelectorAll('.so-current').forEach(n=>n.remove())});

function salesAdviceMetrics(box,items){const grid=document.createElement('div');grid.className='so-advice-grid';items.forEach(([label,value])=>{const div=document.createElement('div'),small=document.createElement('small'),strong=document.createElement('strong');small.textContent=label;strong.textContent=value;div.append(small,strong);grid.append(div)});box.append(grid)}
function salesAdviceNote(box,text,alert=false){const p=document.createElement('p');p.textContent=text;if(alert)p.className='so-alert';box.append(p)}
function renderSalesArticleAdvice(row,box,r,id){box.replaceChildren();const title=document.createElement('h3');title.textContent=id+' · '+(r.article.description||'Artículo');box.append(title);const origin=r.price_reference,i=r.inventory;row.soOrigin=origin;const price=origin.recommended_unit_price;salesAdviceMetrics(box,[['Unidad',r.article.unit_as_documented],['Coste de compra de referencia',r.reference_unit_cost===null?'Sin dato único':money(r.reference_unit_cost)+' EUR'],['Precio orientativo de origen',price===null?'Pendiente de configurar':money(price)+' EUR'],['Margen objetivo',origin.target_margin_percent===null?'Sin configurar':money(origin.target_margin_percent)+' %']]);salesAdviceNote(box,'Precio neto sin IVA, calculado desde la compra histórica y el margen objetivo preparado. Excluye otros costes y no constituye una tarifa aprobada.');if(i)salesAdviceNote(box,'Stock: '+stockNumber(i.physical)+' físico · '+stockNumber(i.reserved)+' reservado · '+stockNumber(i.available)+' disponible / '+i.unit+' · '+stockDate(i.as_of_date)+' · '+(i.material_nature==='SYNTHETIC'?'SINTÉTICO':'Naturaleza pendiente'));else salesAdviceNote(box,'Sin inventario comparable.',true);if(price!==null&&Number(price)>0&&origin.minimum_margin_percent!==null){const discount=origin.maximum_reference_discount_percent;salesAdviceNote(box,'Descuento orientativo máximo sobre este origen: '+money(discount)+' %, antes de logística y regalos. Margen mínimo preparado: '+money(origin.minimum_margin_percent)+' %.');}if(r.latest_sales.length)salesAdviceNote(box,'Últimas ventas comparables: '+r.latest_sales.map(x=>stockDate(x.date)+' · '+stockNumber(x.quantity)+' '+x.unit+' · '+money(x.net_unit_price)+' EUR · '+x.invoice).join(' / '));if(price!==null){const use=document.createElement('button');use.type='button';use.textContent='Usar precio orientativo de origen';use.onclick=()=>{row.querySelector('[data-so=unit_price]').value=stockNumber(price);row.querySelector('[data-so=discount_value]').value='0';salesOfferCalculation++;$('so-summary').replaceChildren();$('so-negotiation').replaceChildren()};box.append(use)}}
function renderSalesNegotiation(n){const box=$('so-negotiation');box.replaceChildren();if(!n)return;const f=n.financial_context;salesAdviceMetrics(box,[['Margen con costes declarados',n.contribution_margin_percent===null?'No calculable':money(n.contribution_margin_percent)+' %'],['Presupuesto máximo para regalo',n.gift_budget===null?'No calculable':money(n.gift_budget)+' EUR'],['Tesorería al corte',f.treasury===null?'Sin dato vinculado':money(f.treasury)+' EUR'],['Fondo de maniobra',f.working_capital===null?'Sin dato vinculado':money(f.working_capital)+' EUR']]);salesAdviceNote(box,'Coste y margen basados en mercancía histórica, logística y regalo declarados. Pueden faltar otros costes. El presupuesto de regalo depende del margen mínimo configurado.');salesAdviceNote(box,f.message,true);if(f.as_of_date)salesAdviceNote(box,'Corte: '+stockDate(f.as_of_date)+' · Pagos documentados antes del cobro: '+money(f.payments_before_collection)+' EUR · Cobros documentados antes del cobro: '+money(f.collections_before_collection)+' EUR. Sumas de vencimientos, no proyección diaria.');if(f.partial)salesAdviceNote(box,'Hay vencimientos sin importe, fecha o moneda comparable. Las sumas mostradas son parciales.',true);if(f.pressure_indicator)salesAdviceNote(box,'Indicio de tensión: se propone anticipar el cobro. Confirmar la previsión completa antes de comprometer condiciones.',true);if(n.below_declared_minimum)salesAdviceNote(box,'El margen calculado queda por debajo del mínimo declarado. Revisa las alternativas antes de negociar.',true);if(n.gift_description)salesAdviceNote(box,'Merchandising propuesto: '+n.gift_description+' · Coste '+money(n.gift_cost)+' EUR. Opción interna; tratamiento fiscal y compromiso pendientes.');n.pending.forEach(p=>salesAdviceNote(box,p,true));n.scenarios.forEach(s=>{const card=document.createElement('article');card.className='so-scenario';const h=document.createElement('h3');h.textContent=s.title;card.append(h);if(s.lines){s.lines.forEach(l=>salesAdviceNote(card,l.article_id+' · Precio neto propuesto: '+(l.net_unit_price===null?'no calculable':money(l.net_unit_price)+' EUR')));salesAdviceNote(card,'Margen orientativo: '+(s.margin_percent===null?'no calculable':money(s.margin_percent)+' %')+' · Portes facturados: '+money(s.freight_charged)+' EUR · Regalo: '+(s.include_gift?'opción mantenida':'sin regalo'));salesAdviceNote(card,'Cobro propuesto: '+stockDate(s.suggested_due_date)+' · '+s.collection_terms);const wording=document.createElement('blockquote');wording.textContent='Podemos proponer estos precios netos, con '+s.collection_terms.toLowerCase()+' Portes facturados: '+money(s.freight_charged)+' EUR. Sujeto a confirmación de la empresa.';card.append(wording);if(s.lines.every(l=>l.net_unit_price!==null)){const apply=document.createElement('button');apply.type='button';apply.textContent='Llevar esta opción al formulario';apply.onclick=()=>{Array.from($('so-lines').children).forEach((row,index)=>{row.querySelector('[data-so=unit_price]').value=stockNumber(s.lines[index].net_unit_price);row.querySelector('[data-so=discount_value]').value='0'});$('so-freight').value=stockNumber(s.freight_charged);$('so-due').value=stockDate(s.suggested_due_date);$('so-payment').value=s.collection_terms;if(!s.include_gift){$('so-gift-description').value='';$('so-gift-cost').value='0'}salesOfferCalculation++;$('so-summary').replaceChildren();document.querySelectorAll('.so-current').forEach(n=>n.remove());box.replaceChildren();$('so-notice').textContent='Opción trasladada. Calcula de nuevo para comprobar importes, IVA y condiciones antes de guardar.'};card.append(apply)}}salesAdviceNote(card,s.message);box.append(card)})}

function renderSalesLineNegotiation(lines){Array.from($('so-lines').children).forEach((row,index)=>{if(!row.soHint||!lines[index])return;const old=row.soHint.querySelector('.so-current');if(old)old.remove();const line=lines[index],current=document.createElement('div');current.className='so-current';salesAdviceMetrics(current,[['Precio negociado neto/unidad',money(Number(line.net_amount)/Number(line.quantity))+' EUR'],['Descuento aplicado',money(line.discount_percent)+' %'],['Margen sobre mercancía',line.reference_margin_percent===null?'No calculable':money(line.reference_margin_percent)+' %']]);salesAdviceNote(current,'Margen de línea antes de logística y merchandising; revisa el margen conjunto abajo.');row.soHint.append(current)})}
'''
